param(
  [string]$ProfileName = 'acceptance',
  [string]$Label = 'initial',
  [ValidateSet('candidate','upgrade-candidate')][string]$CandidateFolder = 'candidate',
  [string]$GatewayUrl = '',
  [ValidateRange(0,65535)][int]$DebugPort = 0,
  [switch]$UseCodexFixture
)
$ErrorActionPreference = 'Stop'
if ($ProfileName -notmatch '^[a-z0-9-]+$' -or $Label -notmatch '^[a-z0-9-]+$') { throw 'Invalid fixture name' }
$taskRoot = $PSScriptRoot
$candidateRoot = Join-Path $taskRoot "$CandidateFolder\Vivary-win32-x64"
$executable = Join-Path $candidateRoot 'vivary.exe'
if (-not (Test-Path -LiteralPath $executable)) { throw 'Verified candidate executable missing' }
$buildMetadata = Get-Content -Raw -LiteralPath (Join-Path $candidateRoot 'resources\workbench\build.json') | ConvertFrom-Json
if ($buildMetadata.sourceCommit -notmatch '^[0-9a-f]{40}$' -or $buildMetadata.sourceDirty) { throw 'Candidate needs clean source metadata' }
$profileRoot = Join-Path $taskRoot "profiles\$ProfileName"
$browserRoot = Join-Path $taskRoot "browsers\$ProfileName"
$evidenceRoot = Join-Path $taskRoot 'evidence'
New-Item -ItemType Directory -Force -Path $profileRoot,$browserRoot,$evidenceRoot | Out-Null
$launchInfo = [System.Diagnostics.ProcessStartInfo]::new()
$launchInfo.FileName = $executable
$launchInfo.WorkingDirectory = $taskRoot
$launchInfo.UseShellExecute = $false
$launchInfo.Arguments = "--user-data-dir=`"$browserRoot`""
if ($DebugPort) {
  if ($DebugPort -ne 43839) { throw 'Acceptance renderer capture uses port 43839 only' }
  $launchInfo.Arguments += " --remote-debugging-address=127.0.0.1 --remote-debugging-port=$DebugPort --force-renderer-accessibility"
}
$launchInfo.Environment.Clear()
foreach ($name in @('SystemRoot','WINDIR','COMSPEC','TEMP','TMP','PATHEXT','OS','SystemDrive','ProgramFiles','ProgramFiles(x86)','ProgramW6432')) {
  $value = [Environment]::GetEnvironmentVariable($name)
  if ($value) { $launchInfo.Environment[$name] = $value }
}
$launchInfo.Environment['USERPROFILE'] = $profileRoot
$launchInfo.Environment['HOME'] = $profileRoot
$launchInfo.Environment['HOMEDRIVE'] = Split-Path -Qualifier $profileRoot
$launchInfo.Environment['HOMEPATH'] = $profileRoot.Substring(2)
$launchInfo.Environment['APPDATA'] = Join-Path $profileRoot 'AppData\Roaming'
$launchInfo.Environment['LOCALAPPDATA'] = Join-Path $profileRoot 'AppData\Local'
$launchInfo.Environment['PATH'] = "$env:SystemRoot\System32;$env:SystemRoot;$env:SystemRoot\System32\WindowsPowerShell\v1.0;C:\Program Files\Git\cmd"
if ($UseCodexFixture) {
  $fixtureRoot = Join-Path $taskRoot 'codex-fixture'
  if (-not (Test-Path -LiteralPath (Join-Path $fixtureRoot 'node_modules\@openai\codex\bin\codex.js'))) { throw 'Codex fixture missing' }
  $launchInfo.Environment['PATH'] = "$fixtureRoot;" + $launchInfo.Environment['PATH']
}
if ($GatewayUrl) {
  $gateway = [uri]$GatewayUrl
  if ($gateway.Scheme -ne 'http' -or $gateway.Host -ne '127.0.0.1') { throw 'Fixture gateway must use loopback HTTP' }
  $launchInfo.Environment['BUILDER_GATEWAY_BASE_URL'] = $GatewayUrl
  $launchInfo.Environment['BUILDER_GATEWAY_TOKEN'] = [guid]::NewGuid().ToString('N')
  $launchInfo.Environment['BUILDER_GATEWAY_SPACE_ID'] = 'windows-acceptance-fixture'
  $launchInfo.Environment['AGENT_ENGINE'] = 'builder'
}
$application = [System.Diagnostics.Process]::Start($launchInfo)
$record = [pscustomobject]@{
  Label = $Label
  Pid = $application.Id
  Executable = $executable
  Profile = $profileRoot
  BrowserProfile = $browserRoot
  SourceCommit = $buildMetadata.sourceCommit
  SyntheticCodex = [bool]$UseCodexFixture
  SyntheticGateway = [bool]$GatewayUrl
  DebugPort = $DebugPort
  StartedAt = (Get-Date).ToUniversalTime().ToString('o')
}
$record | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $evidenceRoot "launch-$Label.json") -Encoding utf8
$record | ConvertTo-Json -Compress
param(
  [Parameter(Mandatory)][string]$LaunchLabel,
  [Parameter(Mandatory)][string]$Label
)
$ErrorActionPreference = 'Stop'
if ($LaunchLabel -notmatch '^[a-z0-9-]+$' -or $Label -notmatch '^[a-z0-9-]+$') { throw 'Invalid evidence label' }
$launch = Get-Content -Raw -LiteralPath (Join-Path $PSScriptRoot "evidence\launch-$LaunchLabel.json") | ConvertFrom-Json
$application = Get-Process -Id $launch.Pid -ErrorAction Stop
if ($application.Path -ne $launch.Executable) { throw 'The launch process identity changed' }
$candidateRoot = [System.IO.Path]::GetDirectoryName($launch.Executable)
$resolvedRoot = [System.IO.Path]::GetFullPath($candidateRoot)
$acceptanceRoot = [System.IO.Path]::GetFullPath($PSScriptRoot) + '\'
if (-not $resolvedRoot.StartsWith($acceptanceRoot, [System.StringComparison]::OrdinalIgnoreCase)) { throw 'Candidate is outside acceptance setup' }
$before = @(Get-CimInstance Win32_Process | Where-Object { $_.ExecutablePath -and $_.ExecutablePath.StartsWith($resolvedRoot + '\', [System.StringComparison]::OrdinalIgnoreCase) } | Select-Object ProcessId,ParentProcessId,Name,CreationDate)
$started = (Get-Date).ToUniversalTime().ToString('o')
$timer = [System.Diagnostics.Stopwatch]::StartNew()
$closeSent = $application.CloseMainWindow()
if (-not $closeSent) { throw 'The app did not accept a normal window close request' }
$mainExited = $application.WaitForExit(25000)
$mainMilliseconds = $timer.Elapsed.TotalMilliseconds
$mainExitedAt = if ($mainExited) { (Get-Date).ToUniversalTime().ToString('o') } else { $null }
$remaining = @()
do {
  $remaining = @(Get-CimInstance Win32_Process | Where-Object { $_.ExecutablePath -and $_.ExecutablePath.StartsWith($resolvedRoot + '\', [System.StringComparison]::OrdinalIgnoreCase) } | Select-Object ProcessId,ParentProcessId,Name,CreationDate)
  if ($remaining.Count -eq 0) { break }
  Start-Sleep -Milliseconds 100
} while ($timer.Elapsed.TotalSeconds -lt 30)
$timer.Stop()
$result = [pscustomobject]@{
  Label = $Label
  SourceCommit = $launch.SourceCommit
  MainPid = $launch.Pid
  CloseRequestedAt = $started
  CloseSent = $closeSent
  MainExited = $mainExited
  MainExitedAt = $mainExitedAt
  MainExitMilliseconds = [Math]::Round($mainMilliseconds, 2)
  AllCandidateProcessesGone = ($remaining.Count -eq 0)
  AllGoneMilliseconds = [Math]::Round($timer.Elapsed.TotalMilliseconds, 2)
  Before = $before
  Remaining = $remaining
}
$json = $result | ConvertTo-Json -Depth 5
[System.IO.File]::WriteAllText((Join-Path $PSScriptRoot "evidence\quit-$Label.json"), $json + "`n", [System.Text.UTF8Encoding]::new($false))
$json
if (-not $mainExited -or $remaining.Count -ne 0) { throw 'Normal close left candidate processes alive' }
// Synthetic Builder JSONL transport. Binds only loopback and never makes requests.
import http from 'node:http';
const port = Number(process.argv[2] || 43838);
if (!Number.isInteger(port) || port < 1024 || port > 65535) throw Error('Invalid port');
const server = http.createServer((req, res) => {
  if (req.method !== 'POST' || new URL(req.url, 'http://127.0.0.1').pathname !== '/messages') {
    res.writeHead(404).end(); return;
  }
  let size = 0;
  req.on('data', chunk => { size += chunk.length; if (size > 8 * 1024 * 1024) req.destroy(); });
  req.on('end', () => {
    res.writeHead(200, { 'Content-Type': 'application/x-ndjson', 'Cache-Control': 'no-store' });
    const send = event => res.write(JSON.stringify(event) + '\n');
    send({ type: 'text-delta', text: 'Synthetic acceptance response is active. ' });
    console.log(JSON.stringify({ event: 'stream-open', at: new Date().toISOString() }));
    const heartbeat = setInterval(() => send({ type: 'heartbeat' }), 1000);
    const deadline = setTimeout(() => {
      send({ type: 'text-delta', text: 'Synthetic bounded response completed.' });
      send({ type: 'stop', reason: 'end_turn' });
      res.end();
    }, 180000);
    res.on('close', () => {
      clearInterval(heartbeat); clearTimeout(deadline);
      console.log(JSON.stringify({ event: 'stream-close', at: new Date().toISOString() }));
    });
  });
});
server.listen(port, '127.0.0.1', () => console.log(JSON.stringify({ listening: port })));
setTimeout(() => { server.closeAllConnections(); server.close(); }, 15 * 60 * 1000);
"""Read only the dedicated issue138 profile. Does not read credentials or payloads."""
import json
import re
import sqlite3
import sys
from pathlib import Path

root = Path("C:/Users/jeffk/AIS-OS/working/2026-10-02/windows-acceptance")
profile = sys.argv[1]
if not re.fullmatch(r"issue138-[a-z0-9-]+", profile):
    raise SystemExit("Dedicated issue138 profile required")
database = root / "profiles" / profile / ".vivary/workbench/auth.sqlite"
if database.resolve() != database.absolute() or not database.is_file():
    raise SystemExit("Missing or redirected fixture database")
db = sqlite3.connect(database.as_uri() + "?mode=ro", uri=True)
