name: computer-use
description: Control Windows apps from ChatGPT
---

# Computer Use

Use this skill to automate the UI of Microsoft Windows apps. It uses SendInput, UI Automation, and Windows.Graphics.Capture screenshots that work even when windows are occluded.

If this plugin is available, read this entire `SKILL.md` once before Windows automation work, before saying Computer Use is unavailable, and before falling back to other Windows automation.

Start with the directions in the Initialize section below. Read these bundled Markdown files relative to this `SKILL.md` when you need information about the specific topic they cover:

- `../../docs/guidance.md`: core runtime behavior, target-window workflow, screenshot handling, and recovery guidance. You MUST read this before controlling Windows apps.
- `../../docs/api.md`: full `sky` API reference. Read this when you need method signatures or object shapes.
- `../../docs/confirmations.md`: you MUST read this before deciding whether a Windows UI action needs confirmation

## Initialize

The bundled `cua_node` `@oai/sky` package is the core entry point for Computer Use. Import it directly by package name from the JavaScript session. Do not spawn `codex-computer-use.exe`, search for the helper executable, or build a custom helper protocol client.

Run this once per fresh `node_repl` JavaScript session:

```js
if (!globalThis.sky) {
  const { sky } = await import("@oai/sky");
  globalThis.sky = sky;
}
```
// Windows packaged acceptance only. No dependencies or application mutations in snapshot mode.
import fs from 'node:fs';
import path from 'node:path';
const root = 'C:/Users/jeffk/AIS-OS/working/2026-10-02/windows-acceptance';
const [command, argument] = process.argv.slice(2);
if (process.platform !== 'win32') throw Error('Windows packaged acceptance only');
if (!['snapshot', 'evaluate'].includes(command)) throw Error('snapshot <label> | evaluate <local.js>');
const same = (a, b) => path.resolve(a).toLowerCase() === path.resolve(b).toLowerCase();
const clean = text => String(text).replace(/https?:\/\/[^\s"'<>]+/g, '<url>')
  .replace(/\/_agent-native\/automations\/webhook\/[^\s"'<>]+/g, '<webhook>')
  .replace(/\b[A-Za-z0-9_-]{43}\b/g, '<opaque>');
function sanitize(value) {
  if (typeof value === 'string') return clean(value);
  if (Array.isArray(value)) return value.map(sanitize);
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([k,v]) => [k,sanitize(v)]));
  return value;
}
let action;
if (command === 'evaluate') {
  const file = path.resolve(argument || '');
  const allowed = path.join(root, 'acceptance-fixture');
  if (!file.toLowerCase().startsWith(allowed.toLowerCase() + path.sep) ||
      path.extname(file) !== '.js' || !same(fs.realpathSync(file), file)) throw Error('Use a reviewed .js file inside acceptance-fixture');
  if (fs.statSync(file).size > 32000) throw Error('Action file too large');
  action = fs.readFileSync(file, 'utf8');
} else if (!/^[a-z0-9-]{1,60}$/.test(argument || '')) throw Error('Invalid screenshot label');
const response = await fetch('http://127.0.0.1:43839/json/list', { signal: AbortSignal.timeout(20000), redirect: 'error' });
if (!response.ok) throw Error('CDP discovery failed');
const targets = (await response.json()).filter(target => {
  try { const url = new URL(target.url);
    return target.type === 'page' && (target.title === 'Vivary' || target.title?.endsWith(' | Vivary')) &&
      url.protocol === 'http:' && url.hostname === '127.0.0.1';
  } catch { return false; }
});
if (targets.length !== 1) throw Error('Expected exactly one loopback Vivary page');
const address = new URL(targets[0].webSocketDebuggerUrl);
if (address.protocol !== 'ws:' || address.hostname !== '127.0.0.1' || address.port !== '43839' ||
    !address.pathname.startsWith('/devtools/page/')) throw Error('Unexpected CDP endpoint');
const socket = new WebSocket(address.href);
const pending = new Map();
let nextId = 0;
socket.addEventListener('message', event => {
  const message = JSON.parse(event.data), item = pending.get(message.id);
  if (!item) return;
  pending.delete(message.id); clearTimeout(item.timer);
  message.error ? item.reject(Error(clean(message.error.message))) : item.resolve(message.result);
});
function failPending() { for (const item of pending.values()) { clearTimeout(item.timer); item.reject(Error('CDP closed')); } pending.clear(); }
socket.addEventListener('close', failPending);
socket.addEventListener('error', failPending);
function rpc(method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = ++nextId;
    const timer = setTimeout(() => { pending.delete(id); reject(Error('CDP RPC timeout')); }, 20000);
    pending.set(id, { resolve, reject, timer }); socket.send(JSON.stringify({ id, method, params }));
  });
}
try {
  await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(Error('CDP connection timeout')), 20000);
    socket.addEventListener('open', () => { clearTimeout(timer); resolve(); }, { once: true });
    socket.addEventListener('error', () => { clearTimeout(timer); reject(Error('CDP connection failed')); }, { once: true });
  });
  if (command === 'snapshot') {
    const evidence = path.join(root, 'evidence');
    if (!same(fs.realpathSync(evidence), evidence)) throw Error('Redirected evidence path');
    const capture = await rpc('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
    fs.writeFileSync(path.join(evidence, 'issue138-' + argument + '.png'), Buffer.from(capture.data, 'base64'), { flag: 'wx' });
    action = "return {title:document.title,path:location.pathname,buttons:[...document.querySelectorAll('button')].map(x=>x.getAttribute('aria-label')||x.innerText),inputs:[...document.querySelectorAll('input,textarea,select')].map(x=>({tag:x.tagName,type:x.type,labels:[...(x.labels||[])].map(l=>l.textContent),ariaLabel:x.getAttribute('aria-label')}))};";
  }
  // Reviewed action bodies may use this same-origin fetch. Never supply remote targets.
  const expression = '(async (fetch) => {' + action + '\n})(async (input,init) => {const u=new URL(typeof input==="string"?input:input.url,location.href);if(u.origin!==location.origin)throw Error("Same-origin actions only");return window.fetch(u.href,{...init,redirect:"error"});})';
  const result = await rpc('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true, timeout: 20000 });
  if (result.exceptionDetails) throw Error(clean(result.exceptionDetails.exception?.description || 'Renderer action failed'));
  console.log(JSON.stringify(sanitize(result.result?.value ?? null)));
} finally { failPending(); socket.close(); }
const response = await fetch('/_agent-native/actions/manage-automation', {
  method: 'POST', headers: { 'Content-Type': 'application/json', 'X-Agent-Native-Frontend': '1' },
  body: JSON.stringify({operation:'create',name:'issue138-schedule',scope:'personal',triggerType:'schedule',
    schedule:'* * * * *',timezone:'America/Denver',body:'Reply with one sentence. Do not call tools.'})
});
const result = await response.json();
if (!response.ok || result.created !== true) throw Error('Schedule creation failed: ' + JSON.stringify(result));
return {status:response.status,created:result.created,name:result.name,nextRun:result.nextRun};
const response = await fetch('/_agent-native/actions/manage-automation', {
  method:'POST',headers: { 'Content-Type': 'application/json', 'X-Agent-Native-Frontend': '1' },
  body:JSON.stringify({operation:'create',name:'issue138-webhook',scope:'personal',triggerType:'webhook',
    body:'Reply with one sentence. Do not call tools.'})
});
const result = await response.json();
if (!response.ok || result.created !== true || typeof result.webhookPath !== 'string') throw Error('Webhook creation failed');
const url = new URL(result.webhookPath,location.href);
if (url.origin !== location.origin) throw Error('Fixture webhook must stay on this app');
const sent = await fetch(url.pathname,{method:'POST',headers:{'Content-Type':'application/json'},
  body:JSON.stringify({fixture:'issue138-webhook-20261002',message:'Interrupt this synthetic acceptance run on normal app close.'})});
const accepted = await sent.json();
if (!sent.ok) throw Error('Fixture webhook was refused');
return {created:result.created,name:result.name,dispatchStatus:sent.status,accepted};
// Use only while the disposable packaged app is closed. No provider calls.
import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
const root = 'C:/Users/jeffk/AIS-OS/working/2026-10-02/windows-acceptance';
const [candidateName, profile, operation = 'create'] = process.argv.slice(2);
if (!['candidate', 'upgrade-candidate'].includes(candidateName) ||
    !/^issue138-[a-z0-9-]+$/.test(profile || '') ||
    !['create', 'pause'].includes(operation)) throw Error('Expected candidate-folder issue138-profile create|pause');
const packageRoot = path.join(root, candidateName, 'Vivary-win32-x64');
const server = path.join(packageRoot, 'resources/workbench/.output/server');
const database = path.join(root, 'profiles', profile, '.vivary/workbench/auth.sqlite');
