for (const item of [packageRoot, database]) if (!same(fs.realpathSync(item), item)) throw Error('Redirected fixture path');
if (process.platform !== 'win32' || !same(process.execPath, path.join(packageRoot, 'resources/node/node.exe'))) {
  throw Error('Run with this candidate bundled Windows Node');
}
