param([Parameter(Mandatory)][ValidateSet('schedule','webhook')][string]$Phase)
$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot
$label = "issue138-merged-$Phase"
$profile = 'issue138-merged'
$fixture = Join-Path $root 'acceptance-fixture'
$evidence = Join-Path $root 'evidence'
$package = Join-Path $root 'upgrade-candidate\Vivary-win32-x64'
$node = Join-Path $package 'resources\node\node.exe'
