Save-FixtureState $after "state-after-$label.json"
$finished = @($after.runs | Where-Object { $_.id -eq $run[0].id })
$agentAfter = @($after.agents | Where-Object { $_.id -eq $run[0].run_id })
if ($finished.Count -ne 1 -or $finished[0].status -ne 'interrupted' -or $finished[0].error_code -ne 'background_automation_interrupted' -or -not $finished[0].finished_at) { throw 'Automation interruption was not persisted' }
if ($agentAfter.Count -ne 1 -or $agentAfter[0].status -ne 'aborted' -or $agentAfter[0].abort_reason -ne 'shutdown' -or -not $agentAfter[0].completed_at) { throw 'Agent shutdown was not persisted' }
