    socket.addEventListener('open', () => { clearTimeout(timer); resolve(); }, { once: true });
    socket.addEventListener('error', () => { clearTimeout(timer); reject(Error('CDP connection failed')); }, { once: true });
  });
  if (command === 'snapshot') {
    const evidence = path.join(root, 'evidence');
    if (!same(fs.realpathSync(evidence), evidence)) throw Error('Redirected evidence path');
    const capture = await rpc('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
    fs.writeFileSync(path.join(evidence, 'issue138-' + argument + '.png'), Buffer.from(capture.data, 'base64'), { flag: 'wx' });
    action = "return {title:document.title,path:location.pathname,buttons:[...document.querySelectorAll('button')].map(x=>x.getAttribute('aria-label')||x.innerText),inputs:[...document.querySelectorAll('input,textarea,select')].map(x=>({tag:x.tagName,type:x.type,labels:[...(x.labels||[])].map(l=>l.textContent),ariaLabel:x.getAttribute('aria-label')}))};";
  }
