param(
  [Parameter(Mandatory)][ValidateSet('schedule','webhook')][string]$Phase,
  [Parameter(Mandatory)][ValidatePattern('^[0-9a-f]{40}$')][string]$SourceCommit,
  [ValidatePattern('^issue138-[a-z0-9-]+$')][string]$RunTag = 'issue138-final'
)
$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot
$label = "$RunTag-$Phase"
$profile = $RunTag
$fixture = Join-Path $root 'acceptance-fixture'
$evidence = Join-Path $root 'evidence'
$package = Join-Path $root 'upgrade-candidate\Vivary-win32-x64'
$node = Join-Path $package 'resources\node\node.exe'
$python = Join-Path $package 'resources\original-runtime\python\python.exe'
$build = Get-Content -Raw -LiteralPath (Join-Path $package 'resources\workbench\build.json') | ConvertFrom-Json
if ($build.sourceCommit -ne $SourceCommit -or $build.sourceDirty) { throw 'Wrong candidate' }
if (Test-Path -LiteralPath (Join-Path $evidence "state-before-$label.json")) { throw 'Inspect existing phase evidence before retrying' }
$gatewayRecordPath = Join-Path $evidence "$RunTag-gateway-process.json"
$gatewayRecord = if (Test-Path -LiteralPath $gatewayRecordPath) { Get-Content -Raw -LiteralPath $gatewayRecordPath | ConvertFrom-Json } else { $null }
$previousGateway = if ($gatewayRecord) { Get-Process -Id $gatewayRecord.Pid -ErrorAction SilentlyContinue } else { $null }
if ($previousGateway) {
  if ($previousGateway.Path -ne $gatewayRecord.Executable -or [Math]::Abs(($previousGateway.StartTime.ToUniversalTime() - [DateTime]::Parse($gatewayRecord.StartedAt).ToUniversalTime()).TotalSeconds) -gt 3) { throw 'Gateway identity changed' }
  $previousGateway | Stop-Process
}
$gatewayLog = Join-Path $evidence "$label-gateway.log"
$gatewayExecutable = Join-Path $root 'candidate\Vivary-win32-x64\resources\node\node.exe'
$gateway = Start-Process -FilePath $gatewayExecutable -ArgumentList @((Join-Path $fixture 'gateway.mjs'),'43838') -WindowStyle Hidden -PassThru -RedirectStandardOutput $gatewayLog -RedirectStandardError (Join-Path $evidence "$label-gateway-error.log")
$gatewayRecord = [pscustomobject]@{Pid=$gateway.Id;Executable=$gatewayExecutable;StartedAt=(Get-Date).ToUniversalTime().ToString('o')}
[IO.File]::WriteAllText($gatewayRecordPath,($gatewayRecord | ConvertTo-Json),[Text.UTF8Encoding]::new($false))
$streamCount = 0
function Read-FixtureState {
  $lines = & $python (Join-Path $fixture 'read-state.py') $profile
  if ($LASTEXITCODE -ne 0) { throw 'Fixture state read failed' }
  return ($lines -join "`n") | ConvertFrom-Json
}
function Save-FixtureState($value,$name) {
  [IO.File]::WriteAllText((Join-Path $evidence $name),($value | ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}
try {
& (Join-Path $root 'launch-candidate.ps1') -ProfileName $profile -Label $label -CandidateFolder upgrade-candidate -GatewayUrl 'http://127.0.0.1:43838' -DebugPort 43839
$deadline = [DateTime]::UtcNow.AddSeconds(60)
do {
  Start-Sleep -Seconds 1
  $ErrorActionPreference = 'Continue'
  $readyText = & $node (Join-Path $fixture 'cdp.mjs') evaluate (Join-Path $fixture 'probe-ready.js') 2>$null
  $readyCode = $LASTEXITCODE
  $ErrorActionPreference = 'Stop'
  $ready = $readyCode -eq 0 -and (($readyText -join "`n") | ConvertFrom-Json).ready
  if ([DateTime]::UtcNow -gt $deadline) { throw 'App readiness timeout' }
} while (-not $ready)
$createdText = & $node (Join-Path $fixture 'cdp.mjs') evaluate (Join-Path $fixture "create-$Phase.js")
if ($LASTEXITCODE -ne 0) { throw 'Fixture creation failed' }
Save-FixtureState ($createdText | ConvertFrom-Json) "create-$label.json"
$deadline = [DateTime]::UtcNow.AddSeconds(110)
do {
  Start-Sleep -Milliseconds 500
  $before = Read-FixtureState
  $run = @($before.runs | Where-Object { $_.automation -eq "issue138-$Phase" -and $_.status -eq 'running' })
  $opened = @(Select-String -LiteralPath $gatewayLog -SimpleMatch 'stream-open').Count -gt $streamCount
  if ([DateTime]::UtcNow -gt $deadline) { Save-FixtureState $before "timeout-$label.json"; throw 'No running fixture with a gateway stream' }
} while ($run.Count -ne 1 -or -not $opened)
$agentBefore = @($before.agents | Where-Object { $_.id -eq $run[0].run_id })
if ($agentBefore.Count -ne 1 -or $agentBefore[0].status -ne 'running') { throw 'Linked agent is not running' }
$runLease = @($before.lease | Where-Object { $_.id -like '*jobs/issue138-schedule.md' })
if ($Phase -eq 'schedule' -and ($runLease.Count -ne 1 -or -not $runLease[0].lease_owner)) { throw 'Scheduled run lease missing' }
Save-FixtureState $before "state-before-$label.json"
& $node (Join-Path $fixture 'cdp.mjs') snapshot "$($RunTag.Substring(9))-$Phase-running"
if ($LASTEXITCODE -ne 0) { throw 'Running screenshot failed' }
& (Join-Path $root 'measure-quit.ps1') -LaunchLabel $label -Label $label
$quit = Get-Content -Raw -LiteralPath (Join-Path $evidence "quit-$label.json") | ConvertFrom-Json
if ($quit.MainExitMilliseconds -ge 12000 -or -not $quit.AllCandidateProcessesGone) { throw 'Shutdown did not finish before the fallback window' }
$after = Read-FixtureState
Save-FixtureState $after "state-after-$label.json"
$finished = @($after.runs | Where-Object { $_.id -eq $run[0].id })
$agentAfter = @($after.agents | Where-Object { $_.id -eq $run[0].run_id })
if ($finished.Count -ne 1 -or $finished[0].status -ne 'interrupted' -or $finished[0].error_code -ne 'background_automation_interrupted' -or -not $finished[0].finished_at) { throw 'Automation interruption was not persisted' }
if ($agentAfter.Count -ne 1 -or $agentAfter[0].status -ne 'aborted' -or $agentAfter[0].abort_reason -ne 'shutdown' -or -not $agentAfter[0].completed_at) { throw 'Agent shutdown was not persisted' }
if (@($after.lease | Where-Object { $_.lease_owner -or $_.lease_expires_at }).Count) { throw 'A lease remains held' }
if ($Phase -eq 'schedule' -and @($after.lease | Where-Object { $_.id -eq $runLease[0].id }).Count) { throw 'Scheduled run lease row remains' }
if ($Phase -eq 'webhook') {
  if (@($before.tasks).Count -ne 1) { throw 'Expected one fixture webhook task' }
  $queued = @($after.tasks | Where-Object { $_.id -eq $before.tasks[0].id })
  if ($queued.Count -ne 1 -or $queued[0].status -ne 'pending' -or $queued[0].completed_at -or $queued[0].attempts -ne 0 -or $queued[0].dispatch_attempts -ne $before.tasks[0].dispatch_attempts) { throw 'Webhook task was not returned to pending with its retry budget restored' }
}
Save-FixtureState ([pscustomobject]@{Phase=$Phase;SourceCommit=$build.sourceCommit;Passed=$true;RunId=$run[0].id;AgentRunId=$run[0].run_id}) "acceptance-$label.json"
"PASS $Phase interruption, persisted outcome, and lease cleanup"
} finally {
  if (-not $gateway.HasExited) { $gateway | Stop-Process }
}

