  $cli = @($processes | Where-Object { $_.CommandLine -like '*codex-fixture*codex.js*app-server*' -and $_.CreationDate.ToUniversalTime() -gt [DateTime]::Parse($launch.StartedAt) })
  if ($workers.Count -eq 1 -and $cli.Count -eq 1) { break }
  if ([DateTime]::UtcNow -gt $deadline) { throw 'Actual Code worker and synthetic CLI did not become live' }
  Start-Sleep -Milliseconds 100
} while ($true)
$holdLog = Join-Path $evidence "$label-creator-hold.log"
