$arguments = @('-NoProfile','-File',('"'+(Join-Path $root 'creator-hold.ps1')+'"'),'-ServerProcessId',[string]$server.Id,'-ServerStartedUtc',$server.StartTime.ToUniversalTime().ToString('o'),'-BundledPythonPath',('"'+$python+'"'),'-BridgePath',('"'+$bridge+'"'),'-FindSeconds','20','-HoldSeconds','60')
$hold = Start-Process -FilePath (Get-Process -Id $PID).Path -ArgumentList $arguments -WindowStyle Hidden -PassThru -RedirectStandardOutput $holdLog -RedirectStandardError $holdError
$deadline = [DateTime]::UtcNow.AddSeconds(15)
do {
  Start-Sleep -Milliseconds 100
  if ($hold.HasExited -or [DateTime]::UtcNow -gt $deadline) { throw 'Original-command observer did not arm' }
} while (-not (Select-String -LiteralPath $holdLog -SimpleMatch '"event":"armed"' -Quiet))
& $node $cdp evaluate (Join-Path $root 'acceptance-fixture\start-original-catalog.js')
if ($LASTEXITCODE -ne 0) { throw 'Original catalog request did not start' }
$deadline = [DateTime]::UtcNow.AddSeconds(10)
do {
  Start-Sleep -Milliseconds 50
  $line = Select-String -LiteralPath $holdLog -SimpleMatch '"event":"creator-suspended"' | Select-Object -First 1
  if ($line) { break }
  if ($hold.HasExited -or [DateTime]::UtcNow -gt $deadline) { throw 'Actual original Python was not held before its command deadline' }
} while ($true)
$creator = $line.Line | ConvertFrom-Json
$all = @(Get-CimInstance Win32_Process)
$ids = [Collections.Generic.HashSet[int]]::new()
$ids.Add($server.Id) | Out-Null
do {
  $count = $ids.Count
  foreach ($item in $all) { if ($ids.Contains([int]$item.ParentProcessId)) { $ids.Add([int]$item.ProcessId) | Out-Null } }
