$required = @([int]$preview.pid,[int]$preview.descendantPid,[int]$workers[0].ProcessId,[int]$cli[0].ProcessId,[int]$creator.pid)
foreach ($requiredId in $required) { if (-not $ids.Contains($requiredId)) { throw 'A required process is outside the server tree' } }
$owned = @($all | Where-Object { $ids.Contains([int]$_.ProcessId) } | Select-Object ProcessId,ParentProcessId,Name,CreationDate)
$timer = [Diagnostics.Stopwatch]::StartNew()
# This is root-only termination. No tree operation or Electron kill is used.
