param([Parameter(Mandatory)][ValidatePattern('^issue138-[a-z0-9-]+$')][string]$Label)
$ErrorActionPreference = 'Stop'
$record = Get-Content -Raw -LiteralPath (Join-Path $PSScriptRoot "evidence\launch-$Label.json") | ConvertFrom-Json
$app = Get-Process -Id $record.Pid -ErrorAction Stop
if ($app.Path -ne $record.Executable -or [Math]::Abs(($app.StartTime.ToUniversalTime() - [DateTime]::Parse($record.StartedAt).ToUniversalTime()).TotalSeconds) -gt 3) { throw 'Owned launch identity changed' }
$candidate = [IO.Path]::GetDirectoryName($record.Executable)
if (-not $candidate.StartsWith($PSScriptRoot + '\', [StringComparison]::OrdinalIgnoreCase)) { throw 'Unexpected candidate path' }
$before = @(Get-CimInstance Win32_Process | Where-Object { $_.ExecutablePath -and $_.ExecutablePath.StartsWith($candidate + '\',[StringComparison]::OrdinalIgnoreCase) } | Select-Object ProcessId,ParentProcessId,Name,CreationDate)
$timer = [Diagnostics.Stopwatch]::StartNew()
Stop-Process -Id $app.Id -Force
do {
  $remaining = @($before | Where-Object { Get-Process -Id $_.ProcessId -ErrorAction SilentlyContinue })
  if ($remaining.Count -eq 0) { break }
  Start-Sleep -Milliseconds 100
} while ($timer.Elapsed.TotalSeconds -lt 25)
$result = @{SourceCommit=$record.SourceCommit;Label=$Label;Action='owned Electron-only forced termination to clear inaccessible chooser';ElapsedMilliseconds=$timer.Elapsed.TotalMilliseconds;Before=$before;Remaining=$remaining;AllGone=($remaining.Count -eq 0)}
[IO.File]::WriteAllText((Join-Path $PSScriptRoot "evidence\cleanup-$Label.json"),($result | ConvertTo-Json -Depth 6),[Text.UTF8Encoding]::new($false))
$result | ConvertTo-Json -Depth 6
if ($remaining.Count -ne 0) { throw 'Owned launch cleanup left processes alive' }

