 $owned = @($servers[0] | Select-Object ProcessId,ParentProcessId,Name,CreationDate)
 $hold = $null
+$modePath = Join-Path $root 'codex-fixture\mode.json'
+$originalMode = [IO.File]::ReadAllBytes($modePath)
+$appOwned = @()
+function Get-RemainingIdentities($records) {
+  @($records | Where-Object {
+    $live = Get-Process -Id $_.ProcessId -ErrorAction SilentlyContinue
+    $live -and [Math]::Abs(($live.StartTime.ToUniversalTime() - $_.CreationDate.ToUniversalTime()).TotalMilliseconds) -lt 1
+  })
+}
 try {
-[IO.File]::WriteAllText((Join-Path $root 'codex-fixture\mode.json'),'{"mode":"held-turn"}',[Text.UTF8Encoding]::new($false))
+[IO.File]::WriteAllText($modePath,'{"mode":"held-turn"}',[Text.UTF8Encoding]::new($false))
@@
 $owned = @($all | Where-Object { $ids.Contains([int]$_.ProcessId) } | Select-Object ProcessId,ParentProcessId,Name,CreationDate)
+$appOwned = @($all | Where-Object { $_.ProcessId -eq $app.Id -or ($_.ParentProcessId -eq $app.Id -and $_.ProcessId -ne $server.Id) } | Select-Object ProcessId,ParentProcessId,Name,CreationDate)
+$liveServer = Get-Process -Id $server.Id -ErrorAction Stop
+if ($liveServer.Path -ne $node -or [Math]::Abs(($liveServer.StartTime.ToUniversalTime() - $serverStarted).TotalMilliseconds) -ge 1) { throw 'Server identity changed before the root-only kill' }
