+    $liveApp = Get-Process -Id $app.Id -ErrorAction SilentlyContinue
+    if ($liveApp -and $liveApp.Path -eq $launch.Executable -and [Math]::Abs(($liveApp.StartTime.ToUniversalTime() - $appStarted).TotalMilliseconds) -lt 1) {
+      $cleanup += $app.Id
+      Stop-Process -Id $app.Id -Force
+      $liveApp.WaitForExit(5000) | Out-Null
+    }
+    $deadline = [DateTime]::UtcNow.AddSeconds(5)
+    do {
+      $cleanupRemaining = @(Get-RemainingIdentities (@($owned)+@($appOwned)))
+      if ($cleanupRemaining.Count -eq 0) { break }
+      Start-Sleep -Milliseconds 100
+    } while ([DateTime]::UtcNow -lt $deadline)
+    $cleanupResult = @{ManualCleanupIsNotProof=$true;SignalledPids=$cleanup;Commands=$cleanupCommands;ObserverExited=$observerExited;Remaining=$cleanupRemaining}
