$exactAllowlist = @('package.json','preview.mjs','descendant.mjs','descendant-mode.json','preview-process.json','descendant-process.json')
if (@(Compare-Object $exactAllowlist $manifest.AddedAllowlist).Count) { throw 'Unexpected restoration allowlist' }
$beforeChecks = @($manifest.OriginalFiles | ForEach-Object {
  $path = [IO.Path]::GetFullPath((Join-Path $project $_.RelativePath))
  if (-not $path.StartsWith($project+'\',[StringComparison]::OrdinalIgnoreCase)) { throw 'Original path escapes fixture' }
