[IO.File]::WriteAllText((Join-Path $root 'evidence\issue138-reused-fixture-restored.json'),($record | ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))
$record | ConvertTo-Json -Depth 5
