$ErrorActionPreference = 'Stop'
$root = [IO.Path]::GetFullPath($PSScriptRoot)
$project = Join-Path $root 'profiles\acceptance\.vivary\workbench\projects\acceptance-positive'
$manifest = Get-Content -Raw -LiteralPath (Join-Path $root 'evidence\acceptance-positive-preservation.json') | ConvertFrom-Json
$archive = Join-Path $root 'evidence\preview-generated-files'
$generated = @('pnpm-lock.yaml','node_modules\.package-map.json','node_modules\.pnpm-workspace-state-v1.json')
$records = @()
foreach ($relative in $generated) {
  if ($relative -in $manifest.OriginalFiles.RelativePath) { throw 'Refusing to remove an original fixture file' }
  $source = [IO.Path]::GetFullPath((Join-Path $project $relative))
  $target = [IO.Path]::GetFullPath((Join-Path $archive $relative))
  if (-not $source.StartsWith($project+'\',[StringComparison]::OrdinalIgnoreCase) -or -not $target.StartsWith($archive+'\',[StringComparison]::OrdinalIgnoreCase)) { throw 'Generated file path escaped the allowlist roots' }
  $item = Get-Item -LiteralPath $source -Force
  if ($item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw 'Unexpected generated file type' }
  if (Test-Path -LiteralPath $target) { throw 'Inspect existing archive before retrying' }
  New-Item -ItemType Directory -Force -Path (Split-Path -Parent $target) | Out-Null
  $hash = (Get-FileHash -LiteralPath $source -Algorithm SHA256).Hash
  Copy-Item -LiteralPath $source -Destination $target
  if ((Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash -ne $hash) { throw 'Generated evidence copy differs' }
  $records += @{File=$relative;Sha256=$hash;CreatedUtc=$item.CreationTimeUtc.ToString('o')}
  Remove-Item -LiteralPath $source
}
$checks = @($manifest.OriginalFiles | ForEach-Object { @{File=$_.RelativePath;HashMatches=((Get-FileHash -LiteralPath (Join-Path $project $_.RelativePath) -Algorithm SHA256).Hash -eq $_.Sha256)} })
$count = @(Get-ChildItem -LiteralPath $project -Recurse -Force -File).Count
$record = @{ArchivedGeneratedFiles=$records;OriginalFiles=$checks;AllOriginalHashesMatch=(@($checks | Where-Object {-not $_.HashMatches}).Count -eq 0);FinalFileCount=$count;ExpectedFileCount=@($manifest.OriginalFiles).Count;OriginalRootDirectoryRetained=$true;GrantChanges=$false}
[IO.File]::WriteAllText((Join-Path $root 'evidence\issue138-fixture-restoration-complete.json'),($record | ConvertTo-Json -Depth 6),[Text.UTF8Encoding]::new($false))
if (-not $record.AllOriginalHashesMatch -or $count -ne @($manifest.OriginalFiles).Count) { throw 'Final fixture preservation check failed' }
$record | ConvertTo-Json -Depth 6

